<?php
declare(strict_types=1);$active_module='hotel_revenue';require_once __DIR__.'/layout.php';if(empty($_SESSION['supplier_csrf']))$_SESSION['supplier_csrf']=bin2hex(random_bytes(32));$u=$supplier_user;$pdo=db();$msg='';$err='';try{if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($_SESSION['supplier_csrf'],(string)($_POST['csrf']??'')))throw new RuntimeException('Güvenlik doğrulaması geçersiz.');$a=$_POST['action']??'';if($a==='tier')$pdo->prepare('INSERT INTO loyalty_tiers(supplier_id,code,name,min_nights,min_revenue,stay_discount_percent,service_discount_percent,bonus_expiry_days) VALUES(?,?,?,?,?,?,?,?)')->execute([$u['supplier_id'],strtoupper(trim((string)$_POST['code'])),trim((string)$_POST['name']),max(0,(int)$_POST['min_nights']),max(0,(float)$_POST['min_revenue']),max(0,(float)$_POST['stay_discount']),max(0,(float)$_POST['service_discount']),$_POST['expiry_days']?:null]);if($a==='segment')$pdo->prepare('INSERT INTO guest_segments(supplier_id,name,rules) VALUES(?,?,?::jsonb)')->execute([$u['supplier_id'],trim((string)$_POST['name']),json_encode(['min_nights'=>(int)$_POST['min_nights'],'nationality'=>strtoupper(trim((string)$_POST['nationality']))])]);if($a==='snapshot')$pdo->prepare('INSERT INTO revenue_snapshots(property_id,snapshot_date,occupancy_percent,adr,revpar,pickup_count,cancellation_count) VALUES(?,?,?,?,?,?,?) ON CONFLICT(property_id,snapshot_date) DO UPDATE SET occupancy_percent=EXCLUDED.occupancy_percent,adr=EXCLUDED.adr,revpar=EXCLUDED.revpar,pickup_count=EXCLUDED.pickup_count,cancellation_count=EXCLUDED.cancellation_count')->execute([(int)$_POST['property_id'],$_POST['date'],(float)$_POST['occupancy'],(float)$_POST['adr'],(float)$_POST['revpar'],(int)$_POST['pickup'],(int)$_POST['cancellations']]);if($a==='recommendation')$pdo->prepare('INSERT INTO revenue_recommendations(property_id,stay_date,recommendation_type,recommended_value,currency,confidence,reason) VALUES(?,?,?,?,?,?,?)')->execute([(int)$_POST['property_id'],$_POST['stay_date'],$_POST['type'],(float)$_POST['value'],$_POST['currency'],(float)$_POST['confidence'],trim((string)$_POST['reason'])]);$msg='Kayıt kaydedildi.';}}catch(Throwable $e){$err=$e->getMessage();}$q=$pdo->prepare("SELECT id,name FROM properties WHERE supplier_id=? AND property_type='hotel'");$q->execute([$u['supplier_id']]);$hotels=$q->fetchAll();$q=$pdo->prepare('SELECT * FROM loyalty_tiers WHERE supplier_id=? ORDER BY min_nights');$q->execute([$u['supplier_id']]);$tiers=$q->fetchAll();$q=$pdo->prepare('SELECT r.*,p.name property_name FROM revenue_snapshots r JOIN properties p ON p.id=r.property_id WHERE p.supplier_id=? ORDER BY r.snapshot_date DESC LIMIT 60');$q->execute([$u['supplier_id']]);$snapshots=$q->fetchAll();$q=$pdo->prepare('SELECT r.*,p.name property_name FROM revenue_recommendations r JOIN properties p ON p.id=r.property_id WHERE p.supplier_id=? ORDER BY r.stay_date LIMIT 60');$q->execute([$u['supplier_id']]);$recommendations=$q->fetchAll();supply_start('Gelir yönetimi, CRM & sadakat',$active_module);?><section class="page-intro"><p>Doluluk, ADR, RevPAR, pickup, iptal, sadakat ve misafir segmentlerini tek ticari görünümden yönetin.</p></section><?php if($msg):?><p class="save-success">✓ <?=htmlspecialchars($msg)?></p><?php endif;?><?php if($err):?><p class="login-error"><?=htmlspecialchars($err)?></p><?php endif;?><section class="next-module"><h2>Sadakat seviyesi</h2><form method="post" class="supply-form"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['supplier_csrf'])?>"><input type="hidden" name="action" value="tier"><div class="form-row"><input name="code" placeholder="GOLD" required><input name="name" placeholder="Gold misafir" required><input type="number" name="min_nights" placeholder="Min. gece" value="0"><input type="number" step="0.01" name="min_revenue" placeholder="Min. gelir" value="0"><input type="number" step="0.01" name="stay_discount" placeholder="Konaklama indirim %" value="0"><input type="number" step="0.01" name="service_discount" placeholder="Hizmet indirim %" value="0"><input type="number" name="expiry_days" placeholder="Puan geçerlilik günü"></div><button>Sadakat seviyesi ekle</button></form><?php foreach($tiers as $t):?><p><b><?=htmlspecialchars($t['name'])?></b> · <?=htmlspecialchars($t['stay_discount_percent'])?>% konaklama · <?=htmlspecialchars($t['service_discount_percent'])?>% hizmet</p><?php endforeach;?></section><section class="next-module"><h2>Gelir günlüğü</h2><form method="post" class="supply-form"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['supplier_csrf'])?>"><input type="hidden" name="action" value="snapshot"><div class="form-row"><select name="property_id"><?php foreach($hotels as $h):?><option value="<?=$h['id']?>"><?=htmlspecialchars($h['name'])?></option><?php endforeach;?></select><input type="date" name="date" value="<?=date('Y-m-d')?>"><input type="number" step="0.01" name="occupancy" placeholder="Doluluk %"><input type="number" step="0.01" name="adr" placeholder="ADR"><input type="number" step="0.01" name="revpar" placeholder="RevPAR"><input type="number" name="pickup" placeholder="Pickup"><input type="number" name="cancellations" placeholder="İptal"></div><button>Günlük veriyi kaydet</button></form><?php foreach($snapshots as $s):?><p><b><?=htmlspecialchars($s['property_name'])?></b> · <?=htmlspecialchars($s['snapshot_date'])?> · doluluk <?=htmlspecialchars($s['occupancy_percent'])?>% · ADR <?=htmlspecialchars($s['adr'])?> · RevPAR <?=htmlspecialchars($s['revpar'])?></p><?php endforeach;?></section><section class="next-module"><h2>Fiyat önerisi</h2><form method="post" class="supply-form"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['supplier_csrf'])?>"><input type="hidden" name="action" value="recommendation"><div class="form-row"><select name="property_id"><?php foreach($hotels as $h):?><option value="<?=$h['id']?>"><?=htmlspecialchars($h['name'])?></option><?php endforeach;?></select><input type="date" name="stay_date"><select name="type"><option value="raise_rate">Fiyat artır</option><option value="lower_rate">Fiyat indir</option><option value="close_channel">Kanal kapat</option></select><input type="number" step="0.01" name="value" placeholder="Önerilen değer"><select name="currency"><option>EUR</option><option>TRY</option><option>USD</option></select><input type="number" step="0.01" name="confidence" placeholder="Güven %"><input name="reason" placeholder="Gerekçe"></div><button>Öneri oluştur</button></form><?php foreach($recommendations as $r):?><p><b><?=htmlspecialchars($r['property_name'])?></b> · <?=htmlspecialchars($r['stay_date'])?> · <?=htmlspecialchars($r['recommendation_type'])?> <?=htmlspecialchars($r['recommended_value'])?> <?=htmlspecialchars($r['currency'])?> · <?=htmlspecialchars($r['reason'])?></p><?php endforeach;?></section><?php supply_end();
